using SteamKit2;
using System.Text.Json;
var client = new SteamClient();
var user = client.GetHandler<SteamUser>()!;
var apps = client.GetHandler<SteamApps>()!;
var manager = new CallbackManager(client);
var logged = new TaskCompletionSource<bool>();
using var connected = manager.Subscribe<SteamClient.ConnectedCallback>(_ => user.LogOnAnonymous());
using var logon = manager.Subscribe<SteamUser.LoggedOnCallback>(v => {
 if (v.Result == EResult.OK) logged.TrySetResult(true);
 else logged.TrySetException(new Exception("Anonymous Steam login: "+v.Result));
});
using var stop = new CancellationTokenSource(TimeSpan.FromSeconds(65));
var callbacks = Task.Run(async () => {while (!stop.IsCancellationRequested) {
 try {await manager.RunWaitCallbackAsync(stop.Token);} catch (OperationCanceledException) {break;}
}});
client.Connect();
try {
 await logged.Task.WaitAsync(stop.Token);
 var output = new Dictionary<string,object>();
 foreach (uint id in new uint[]{976730,1064270}) {
  var tokens=await apps.PICSGetAccessTokens(new[]{id},Array.Empty<uint>());
  var request=new SteamApps.PICSRequest(id);
  if(tokens.AppTokens.TryGetValue(id,out var token))request.AccessToken=token;
  var info=await apps.PICSGetProductInfo(new[]{request},Array.Empty<SteamApps.PICSRequest>());
  foreach(var part in info.Results)foreach(var pair in part.Apps) {
   object Convert(KeyValue node)=>node.Children.Count>0
    ? node.Children.GroupBy(c=>c.Name).ToDictionary(g=>g.Key,g=>Convert(g.Last()))
    : node.Value??"";
   output[id.ToString()]=new {change_number=pair.Value.ChangeNumber,common=Convert(pair.Value.KeyValues["common"]),depots=Convert(pair.Value.KeyValues["depots"])};
  }
 }
 Console.WriteLine(JsonSerializer.Serialize(output));
} finally {client.Disconnect();stop.Cancel();await callbacks;}
